from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-04/first-bloom-head-r20'
assert json.loads((OUT/'head-rig-verification.json').read_text())['result'].startswith('PASS')
source=(ROOT/'tools/build-first-bloom-feet-review.py').read_text()
for old,new in [('first-bloom-feet-r15','first-bloom-head-r20'),('first-bloom-trim-r14','first-bloom-shoulders-r19'),('8830','8886'),('8810','8884'),('8,830','8,886'),('1.423','1.432'),('132','148'),('revision 15','revision 20'),('Revision 15','Revision 20'),('revision 14','revision 19'),('Revision 14','Revision 19'),('root feet','compact concept crown'),('root-feet review','compact-head review'),('foot-refinement.json','head-refinement.json')]:source=source.replace(old,new)
source=source.replace('The existing foot loops now form broader root fans with unequal crooked toes, lower contact pads, and flattened, staggered fungal brackets around the ankles. All ten root bases are seated into the leg surface with matching skin weights. The approved chest shaping is preserved.', 'The mushroom crown is compressed vertically by 20% above its base, bringing the overlapping caps closer to the shoulders. A gentle forward sweep increases the lower cap overhang in profile while retaining the broad crown and small crest. Hanging tissue and dependent crosslinks are reseated against their supports. The rest of the body retains its previous scale, and the saved skeleton is unchanged.')
height=json.loads((OUT/'refinement-metrics.json').read_text())['study_height_metres']
source=source.replace('No new triangles were added during foot shaping. Reauditing buried geometry removes 422 triangles from the untrimmed model; retaining the new ankle contacts leaves 20 more triangles than revision 19.', f'No new geometry was added. Reauditing buried faces leaves two more triangles than revision 19. One mesh, one material and four 512px maps are retained. Crown compression and flatter cap centers reduce the art-study height from 4.65 m to approximately {height:.3f} m; the torso and limbs are not enlarged to compensate.')
source=source.replace("[('feet-front','Root spread from the front'),('feet-angle','Root fans and ankle transition'),('feet-side','Foot depth and bracket profile')]", "[('head-front','Compact overlapping crown'),('head-angle','Crown overhang and hanging tissue'),('head-side','Head profile')]")
source=source.replace('<h2>Concept reference</h2>','<p><a href="head-rig-verification.json">Saved skeleton check</a> · <a href="head-refinement.json">Head compression measurements</a></p><h2>Concept reference</h2>')
source=source.replace('<h2>Concept reference</h2>','<h2>Your head shape guides</h2><div class="pair"><figure><img src="head-reference-front.png" alt="User front head reference"><figcaption>Front and three-quarter crown guide</figcaption></figure><figure><img src="head-reference-side.png" alt="User side head reference"><figcaption>Side profile guide</figcaption></figure></div><h2>Full concept reference</h2>')
exec(compile(source,str(__file__),'exec'))
